<script lang="ts">import type { InventoryItem } from '$lib/api/types'; let { part, expanded, onToggle }: { part: { part_num:string; part_name:string; total:number; colors:InventoryItem[] }; expanded:boolean; onToggle:()=>void } = $props();</script>
<article class="ledger-row"><div class="part"><button aria-label={`${expanded ? 'Collapse' : 'Expand'} ${part.part_name}`} onclick={onToggle}>{expanded ? '−' : '+'}</button><strong>{part.part_name}</strong><span>{part.part_num}</span></div><div>{part.total}</div><div>{part.colors.length} colors</div><div>{[...new Set(part.colors.flatMap((color)=>color.source_set_nums))].join(', ')}</div>{#if expanded}<div class="colors">{#each part.colors as color}<div><i style={`background:#${color.rgb_hex}`}></i><span>{color.color_name}</span><b>{color.quantity}</b><small>{color.source_set_nums.join(', ')}</small></div>{/each}</div>{/if}</article>
<style>.ledger-row{display:grid;grid-template-columns:minmax(220px,2fr) .5fr .75fr 1fr;gap:10px;padding:11px;border-bottom:1px solid var(--line);align-items:center}.part{display:flex;align-items:center;gap:7px}.part span,small{color:var(--ink-muted);font-size:.78rem}.part button{width:26px;height:26px;border:1px solid var(--ink);background:var(--surface);font-weight:800}.colors{grid-column:1/-1;padding:6px 0 2px 34px}.colors div{display:grid;grid-template-columns:16px 1fr 36px 1fr;gap:8px;padding:6px 0}.colors i{width:14px;height:14px;border:1px solid #555}@media(max-width:719px){.ledger-row{grid-template-columns:1fr auto}.ledger-row>div:nth-child(3),.ledger-row>div:nth-child(4){grid-column:1/-1;color:var(--ink-muted);font-size:.8rem}.colors{grid-column:1/-1;padding-left:0}.colors div{grid-template-columns:16px 1fr 36px}.colors small{grid-column:2/-1}}</style>
